#!/usr/bin/env bash
# LG-QSDMA-r11 device recipe (comm slice; source-only; NOT executed by the Implementor). BUILD_CCO_SDMA=1 is REQUIRED (header default 0 = silent no-op put).
# GEMM to a gfx950 code object, extracts the hsaco, records resource usage + ASM, and writes the expected-hash header.
# Fresh BUILD_DIR mandatory. Modeled on PR695-M4/build_device.sh (explicit --offload-arch=gfx950).
set -euo pipefail
LG="${LG:-/work/candidates/LG-QSDMA-r11}"
AITER_INC="${AITER_INC:?aiter csrc/include (opus.hpp + hip_minimal.hpp; pin the same files as PR695-M4/private_deps)}"
MORI_ROOT="${MORI_ROOT:-/reference-mori}"
HIPCC="${HIPCC:-/opt/rocm/bin/hipcc}"
BUNDLER="${BUNDLER:-/opt/rocm/llvm/bin/clang-offload-bundler}"
OBJCOPY="${OBJCOPY:-objcopy}"
LG_L1C_SWIZZLE="${LG_L1C_SWIZZLE:-0}"; LG_L2A_BYPASS="${LG_L2A_BYPASS:-0}"; LG_L2B_ONE_RELEASE="${LG_L2B_ONE_RELEASE:-1}"   # r5 option flags (default 0 = r4b behaviour)
LG_STAMPS="${LG_STAMPS:-0}"; LG_NEGCTRL_NOWB="${LG_NEGCTRL_NOWB:-0}"; LG_NEGCTRL_NOWAIT="${LG_NEGCTRL_NOWAIT:-0}"; LG_NEGCTRL_ISO="${LG_NEGCTRL_ISO:-0}"; LG_ISO_DELAY_ITERS="${LG_ISO_DELAY_ITERS:-0}"                                                             # debug / negative control (NEVER for timing)
LG_DEBUG_POSTCOUNT="${LG_DEBUG_POSTCOUNT:-0}"   # 1 = per-(dst,chunk) post_count (debug build; extra atomic per put; NOT for timing)
LG_NEGCTRL_NOCAS="${LG_NEGCTRL_NOCAS:-0}"       # 1 = negative control (non-atomic READY->POSTING claim); must show duplicate puts; NEVER for timing
LG_R6_POSTER="${LG_R6_POSTER:-1}"; LG_X_INDEXER="${LG_X_INDEXER:-1}"; LG_R6_ARRIVAL_ACQ="${LG_R6_ARRIVAL_ACQ:-0}"; LG_X_FORCE_TIMEOUT_G1="${LG_X_FORCE_TIMEOUT_G1:-0}"; LG_X_FORCE_TIMEOUT_G0="${LG_X_FORCE_TIMEOUT_G0:-0}"; LG_R8_FOLD="${LG_R8_FOLD:-0}"; LG_NO_GRIDREAD="${LG_NO_GRIDREAD:-1}"; LG_X_NEG_DOUBLE_PUT="${LG_X_NEG_DOUBLE_PUT:-0}"; LG_X_POSTER_LAST="${LG_X_POSTER_LAST:-0}"   # r6x flags: the HOST build must use the SAME LG_R6_POSTER/LG_X_INDEXER (grid size + plan code); puts per peer = ENTRY (n1/n2/n4), no build-time n
LG_REMOTE_HALF="${LG_REMOTE_HALF:-0}"   # r4 variant switch: 1 = remote half-N items (default), 0 = r3 full remote tiles. SAME value for host build!
BUILD_DIR="${BUILD_DIR:?set BUILD_DIR to a fresh, non-existent output directory}"
[ -e "${BUILD_DIR}" ] && { echo "refuse: BUILD_DIR exists (${BUILD_DIR})" >&2; exit 1; }
bash -n "${BASH_SOURCE[0]}"
( cd "${LG}" && sha256sum -c "${LG}/SOURCE_SHA256.txt" )
mkdir -p "${BUILD_DIR}/gen" "${BUILD_DIR}/img"
FLAGS=( -I"${LG}/device" -I"${LG}/interface" -I"${AITER_INC}" -I"${MORI_ROOT}/include" -DBUILD_CCO_SDMA=1 -DLG_REMOTE_HALF=${LG_REMOTE_HALF} -DLG_R6_POSTER=${LG_R6_POSTER:-1} -DLG_X_INDEXER=${LG_X_INDEXER:-1} -DLG_R6_ARRIVAL_ACQ=${LG_R6_ARRIVAL_ACQ} -DLG_X_FORCE_TIMEOUT_G1=${LG_X_FORCE_TIMEOUT_G1} -DLG_X_FORCE_TIMEOUT_G0=${LG_X_FORCE_TIMEOUT_G0} -DLG_R8_FOLD=${LG_R8_FOLD} -DLG_NO_GRIDREAD=${LG_NO_GRIDREAD} -DLG_X_NEG_DOUBLE_PUT=${LG_X_NEG_DOUBLE_PUT} -DLG_X_POSTER_LAST=${LG_X_POSTER_LAST} -DLG_DEBUG_POSTCOUNT=${LG_DEBUG_POSTCOUNT} -DLG_NEGCTRL_NOCAS=${LG_NEGCTRL_NOCAS} -DLG_L1C_SWIZZLE=${LG_L1C_SWIZZLE} -DLG_L2A_BYPASS=${LG_L2A_BYPASS} -DLG_L2B_ONE_RELEASE=${LG_L2B_ONE_RELEASE} -DLG_STAMPS=${LG_STAMPS} -DLG_NEGCTRL_NOWB=${LG_NEGCTRL_NOWB} -DLG_NEGCTRL_NOWAIT=${LG_NEGCTRL_NOWAIT} -DLG_NEGCTRL_ISO=${LG_NEGCTRL_ISO} -DLG_ISO_DELAY_ITERS=${LG_ISO_DELAY_ITERS}
        -D__HIPCC_RTC__ -DOPUS_TILE_CONTAINER=0
        -std=c++20 -O3 -fno-fast-math --offload-arch=gfx950 )
{ echo "# LG-QSDMA-r11 device build"; "${HIPCC}" --version; echo "FLAGS: ${FLAGS[*]}"; } | tee "${BUILD_DIR}/build-command.txt"
src="${LG}/device/gemm_quad_fp8_comm.cu"; so="${BUILD_DIR}/img/lg_gemm_quad_fp8_comm.so"
# resource usage (VGPR/AGPR/SGPR/spill/scratch/LDS) in the build log
"${HIPCC}" "${FLAGS[@]}" -Rpass-analysis=kernel-resource-usage -fPIC -shared "${src}" -o "${so}" 2> "${BUILD_DIR}/resource-usage.log" || { cat "${BUILD_DIR}/resource-usage.log" >&2; exit 4; }
cat "${BUILD_DIR}/resource-usage.log"
"${HIPCC}" "${FLAGS[@]}" --cuda-device-only -S "${src}" -o "${BUILD_DIR}/img/lg_gemm_quad_fp8_comm.gfx950.s"
"${OBJCOPY}" -O binary --only-section=.hip_fatbin "${so}" "${BUILD_DIR}/img/lg.fatbin"
tgt="$("${BUNDLER}" --type=o --input="${BUILD_DIR}/img/lg.fatbin" --list | grep gfx950 | head -n1)"
[ -n "${tgt}" ] || { echo "NO gfx950 bundle entry" >&2; exit 3; }
"${BUNDLER}" --type=o --unbundle --targets="${tgt}" --input="${BUILD_DIR}/img/lg.fatbin" --output="${BUILD_DIR}/img/lg_gemm_quad_fp8_comm.hsaco"
echo "LG_DEVICE_BUILD_OK target=${tgt}"
HS="$(sha256sum "${BUILD_DIR}/img/lg_gemm_quad_fp8_comm.hsaco" | cut -d' ' -f1)"
cat > "${BUILD_DIR}/gen/lg_expected_hashes.h" <<EOF
// GENERATED by LG-QSDMA-r11 build_device.sh; actual code-object SHA256.
#pragma once
#define LG_EXPECTED_HSACO_SHA256 "${HS}"
EOF
cat "${BUILD_DIR}/gen/lg_expected_hashes.h"
# static gates for Evidence: expect LDS 135168(+0), no scratch; MFMA f8f6f4 16x16x128; ds_read_b128; buffer_load..lds
grep -cE "v_mfma_.*f8f6f4|v_mfma_f32_16x16x128" "${BUILD_DIR}/img/lg_gemm_quad_fp8_comm.gfx950.s" | sed 's/^/mfma_lines=/' || true
grep -cE "ds_read_b128" "${BUILD_DIR}/img/lg_gemm_quad_fp8_comm.gfx950.s" | sed 's/^/ds_read_b128=/' || true
grep -E "scratch|\.private_segment_fixed_size|\.group_segment_fixed_size" "${BUILD_DIR}/img/lg_gemm_quad_fp8_comm.gfx950.s" | head -n 20 || true
